/* Sheet and Drawer: the modal glass (--modal-* tokens) flush to one edge of
   the viewport. Only the inner corners round; the edge it slides from stays
   square. The header keeps one left edge, close button at its right. */

.root {
  position: fixed;
  inset: 0;
  z-index: var(--z-modal);
}

.scrim {
  position: absolute;
  inset: 0;
  background: var(--modal-scrim);
  -webkit-backdrop-filter: var(--modal-scrim-blur);
  backdrop-filter: var(--modal-scrim-blur);
  animation: fade-in 240ms var(--ease);
}

.root[data-state="closed"] .scrim {
  opacity: 0;
  transition: opacity 240ms var(--ease);
}

.panel {
  --sheet-r: var(--sheet-radius, var(--r-xl));
  position: absolute;
  display: flex;
  flex-direction: column;
  max-width: 100vw;
  max-height: 100dvh;
  overflow: hidden;
  background: var(--modal-surface);
  -webkit-backdrop-filter: var(--modal-blur);
  backdrop-filter: var(--modal-blur);
  box-shadow: var(--modal-shadow);
  color: var(--ink-body);
  outline: none;
  transition: transform 240ms var(--ease-out);
}

.right,
.left {
  top: 0;
  bottom: 0;
  width: min(var(--sheet-size, 420px), 100vw);
}

.right {
  right: 0;
  border-radius: var(--sheet-r) 0 0 var(--sheet-r);
  animation: sheet-in-right 260ms var(--ease-out);
}

.left {
  left: 0;
  border-radius: 0 var(--sheet-r) var(--sheet-r) 0;
  animation: sheet-in-left 260ms var(--ease-out);
}

.top,
.bottom {
  left: 0;
  right: 0;
  height: auto;
  max-height: min(var(--sheet-size, 85dvh), 100dvh);
}

.top {
  top: 0;
  border-radius: 0 0 var(--sheet-r) var(--sheet-r);
  animation: sheet-in-top 260ms var(--ease-out);
}

.bottom {
  bottom: 0;
  border-radius: var(--sheet-r) var(--sheet-r) 0 0;
  animation: sheet-in-bottom 260ms var(--ease-out);
}

.root[data-state="closed"] .right {
  transform: translateX(100%);
}

.root[data-state="closed"] .left {
  transform: translateX(-100%);
}

.root[data-state="closed"] .top {
  transform: translateY(-100%);
}

.root[data-state="closed"] .bottom {
  transform: translateY(100%);
}

/* Drawer: a bottom sheet centred to a readable width on wide screens. */
.drawer.bottom {
  left: 50%;
  right: auto;
  width: min(var(--drawer-width, 640px), 100vw);
  margin-left: calc(min(var(--drawer-width, 640px), 100vw) / -2);
}

.handleArea {
  display: flex;
  justify-content: center;
  padding: 10px 0 2px;
  touch-action: none;
}

.draggable {
  cursor: grab;
}

.draggable:active {
  cursor: grabbing;
}

.handle {
  width: 40px;
  height: 4px;
  border-radius: var(--r-full);
  background: rgba(var(--rgb-brand-deep), 0.18);
}

/* Inline: the panel standing in the page flow, every corner rounded. */
.inline {
  position: relative;
  inset: auto;
  margin: 0;
  max-height: none;
  border-radius: var(--sheet-r);
  animation: none;
}

.inline.right,
.inline.left {
  width: var(--sheet-size, 380px);
}

.inline.top,
.inline.bottom,
.inline.drawer.bottom {
  left: auto;
  width: var(--sheet-size, 420px);
  margin-left: 0;
}

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: calc(20px * var(--density)) calc(16px * var(--density)) calc(14px * var(--density)) calc(24px * var(--density));
  border-bottom: var(--border-w) solid var(--line-glass);
}

.drawer .header {
  padding-top: calc(8px * var(--density));
}

.heading {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.title {
  font-family: var(--font-display);
  font-size: var(--sheet-title-size, 18px);
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: var(--tracking-display);
  color: var(--ink-heading);
}

.description {
  font-size: var(--text-small);
  line-height: 1.5;
  color: var(--ink-secondary);
}

.close {
  flex-shrink: 0;
  margin-top: -4px;
}

.body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: calc(18px * var(--density)) calc(24px * var(--density));
}

.footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
  padding: calc(14px * var(--density)) calc(24px * var(--density));
  border-top: var(--border-w) solid var(--line-glass);
}

@keyframes sheet-in-right {
  from {
    transform: translateX(100%);
  }
}

@keyframes sheet-in-left {
  from {
    transform: translateX(-100%);
  }
}

@keyframes sheet-in-top {
  from {
    transform: translateY(-100%);
  }
}

@keyframes sheet-in-bottom {
  from {
    transform: translateY(100%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .panel {
    animation: fade-in var(--dur) linear;
    transition: none;
  }

  .inline {
    animation: none;
  }
}

"use client";

import { useId, useRef, useState, type PointerEvent, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { Portal } from "../_internal/portal";
import { useDialogBehaviour, usePresence } from "../AlertDialog/dialog-core";
import { IconX } from "../Icon/Icon";
import { IconButton } from "../IconButton/IconButton";
import { themedScrollClass } from "../Scroll/ScrollArea";
import styles from "./Sheet.module.css";

export type SheetSide = "right" | "left" | "top" | "bottom";

export type SheetProps = {
  open: boolean;
  /** Esc, the scrim and the close button. */
  onClose: () => void;
  title: ReactNode;
  description?: ReactNode;
  children?: ReactNode;
  /** Buttons along the bottom edge, primary last. */
  footer?: ReactNode;
  /** The edge it slides in from. */
  side?: SheetSide;
  /** Width (left, right) or height (top, bottom), any CSS length. Defaults to --sheet-size, 420px. */
  size?: string;
  closeLabel?: string;
  /** Render the open panel in the page flow: no portal, scrim, focus trap or scroll lock (docs, previews). */
  inline?: boolean;
  className?: string;
};

export type DrawerProps = Omit<SheetProps, "side" | "size"> & {
  /** Let a downward drag on the handle dismiss it. On by default. */
  dragToClose?: boolean;
};

/**
 * A panel that slides in from an edge over a scrim: secondary tasks that
 * keep the page in view (filters, a record's details, settings). A dialog
 * in every other respect: focus moves in and is trapped, Esc and the scrim
 * close it, page scroll is locked and focus returns to the opener. The
 * header keeps one left edge, with the close button at its right.
 */
export function Sheet(props: SheetProps) {
  const present = usePresence(props.open, 260);
  if (props.inline) return <SheetFrame {...props} open />;
  if (!present) return null;
  return <SheetFrame {...props} />;
}

/** A bottom sheet with a grab handle, the mobile pattern. Drag the handle down to dismiss. */
export function Drawer({ dragToClose = true, ...props }: DrawerProps) {
  const present = usePresence(props.open, 260);
  if (props.inline) return <SheetFrame {...props} side="bottom" drawer dragToClose={false} open />;
  if (!present) return null;
  return <SheetFrame {...props} side="bottom" drawer dragToClose={dragToClose} />;
}

function SheetFrame({
  open,
  onClose,
  title,
  description,
  children,
  footer,
  side = "right",
  size,
  closeLabel = "Close",
  inline,
  className,
  drawer,
  dragToClose,
}: SheetProps & { drawer?: boolean; dragToClose?: boolean }) {
  const id = useId();
  const panelRef = useRef<HTMLDivElement>(null);
  const { onKeyDown } = useDialogBehaviour({ open, panelRef, onEscape: onClose, enabled: !inline });
  const [drag, setDrag] = useState(0);
  const dragStart = useRef<number | null>(null);

  const onHandleDown = (e: PointerEvent<HTMLDivElement>) => {
    if (!dragToClose) return;
    dragStart.current = e.clientY;
    e.currentTarget.setPointerCapture(e.pointerId);
  };
  const onHandleMove = (e: PointerEvent<HTMLDivElement>) => {
    if (dragStart.current === null) return;
    setDrag(Math.max(0, e.clientY - dragStart.current));
  };
  const onHandleUp = () => {
    if (dragStart.current === null) return;
    const h = panelRef.current?.offsetHeight ?? 1;
    dragStart.current = null;
    if (drag > Math.min(160, h * 0.3)) onClose();
    setDrag(0);
  };

  const panel = (
    <div data-slot="sheet"
      ref={panelRef}
      role="dialog"
      aria-modal={inline ? undefined : true}
      aria-labelledby={`${id}-t`}
      aria-describedby={description ? `${id}-d` : undefined}
      tabIndex={-1}
      data-side={side}
      data-state={open ? "open" : "closed"}
      data-surface="solid"
      className={cx(styles.panel, styles[side], drawer && styles.drawer, inline && styles.inline, className)}
      style={{
        ...(size ? { ["--sheet-size" as string]: size } : null),
        ...(drag ? { transform: `translateY(${drag}px)`, transition: "none" } : null),
      }}
      onKeyDown={onKeyDown}
    >
      {drawer ? (
        <div
          className={cx(styles.handleArea, dragToClose && styles.draggable)}
          onPointerDown={onHandleDown}
          onPointerMove={onHandleMove}
          onPointerUp={onHandleUp}
          onPointerCancel={onHandleUp}
          aria-hidden="true"
        >
          <span className={styles.handle} />
        </div>
      ) : null}
      <header className={styles.header}>
        <div className={styles.heading}>
          <h2 id={`${id}-t`} className={styles.title}>
            {title}
          </h2>
          {description ? (
            <p id={`${id}-d`} className={styles.description}>
              {description}
            </p>
          ) : null}
        </div>
        <IconButton icon={<IconX size={18} />} label={closeLabel} variant="ghost" onClick={onClose} className={styles.close} />
      </header>
      {children ? <div className={cx(styles.body, themedScrollClass)}>{children}</div> : null}
      {footer ? <footer className={styles.footer}>{footer}</footer> : null}
    </div>
  );

  if (inline) return panel;
  return (
    <Portal>
      <div className={styles.root} data-state={open ? "open" : "closed"}>
        <div className={styles.scrim} aria-hidden="true" onClick={onClose} />
        {panel}
      </div>
    </Portal>
  );
}
